import fs from 'node:fs';import{pages}from'./sitewide-seo-20261101/data.mjs';import{routeOwner}from'./public-closeout-20261101/route-owner.mjs';
const account='9e5386dcf455be34c582d93f8bfc79e6',zone='66ec3268950adcfc837b7b8b2f8356ed';async function get(p){const r=await fetch('https://api.cloudflare.com/client/v4'+p,{headers:{Authorization:'Bearer '+process.env.CLOUDFLARE_API_TOKEN}}),j=await r.json();if(!j.success)throw Error('Read-only owner inspection failed');return j.result;}const routes=await get('/zones/'+zone+'/workers/routes'),names=[...new Set([...Object.keys(pages),'/sitemap.xml'].map(p=>routeOwner(routes,'https://shiftsometimber.co.uk'+p).script))],workers=[];for(const name of names){const all=await get('/accounts/'+account+'/workers/scripts/'+name+'/deployments'),deployment=all.deployments.sort((a,b)=>b.created_on.localeCompare(a.created_on))[0],v=deployment.versions.find(x=>x.percentage===100),version=await get('/accounts/'+account+'/workers/workers/'+name+'/versions/'+v.version_id+'?include=modules');workers.push({name,deployment:deployment.id,versionId:v.version_id,seoInstalled:version.modules.some(m=>m.name.startsWith('sitewide-seo-20261101/'))});}fs.mkdirSync('seo-owner-evidence',{recursive:true});const report={readOnly:true,checkedAt:new Date().toISOString(),workers};fs.writeFileSync('seo-owner-evidence/owners.json',JSON.stringify(report,null,2));console.log('SEO_LIVE_OWNER_STATE '+JSON.stringify(report));
const{chromium}=await import('./seo-page-tools/node_modules/playwright/index.mjs'),browser=await chromium.launch({headless:true,channel:'chrome',args:['--no-sandbox']});try{const context=await browser.newContext({viewport:{width:1440,height:1050},serviceWorkers:'block'});await context.route('**/*',r=>['POST','PUT','PATCH','DELETE'].includes(r.request().method())?r.abort():r.continue());const page=await context.newPage();await page.goto('https://shiftsometimber.co.uk/articles/mens-weight-loss-diet',{waitUntil:'load'});const images=await page.locator('main img').evaluateAll(es=>es.map(e=>({loading:e.loading,complete:e.complete,naturalWidth:e.naturalWidth,top:e.getBoundingClientRect().top})));const firstLazy=page.locator('main img[loading="lazy"]').first();let result='none';if(await firstLazy.count()){result=await Promise.race([firstLazy.evaluate(i=>i.decode()).then(()=> 'decoded',e=>'decode-error:'+e.message),new Promise(r=>setTimeout(()=>r('timed-out-before-scroll'),30000))]);await firstLazy.scrollIntoViewIfNeeded();const after=await Promise.race([firstLazy.evaluate(i=>i.decode()).then(()=> 'decoded-after-scroll',e=>'decode-error-after-scroll:'+e.message),new Promise(r=>setTimeout(()=>r('timed-out-after-scroll'),15000))]);report.lazyImage={images,result,after};}fs.writeFileSync('seo-owner-evidence/lazy-image.json',JSON.stringify(report.lazyImage,null,2));console.log('SEO_LAZY_IMAGE_DIAGNOSTIC '+JSON.stringify(report.lazyImage));}finally{await browser.close();}
